// =============================================================================
// File: tb/sim_main.cpp
// Description: Full-field Verilator regression against the independent Python
//              ITCH 5.0 reference model. Vectors are generated by
//              `python tb/itch_model.py --count N --out tb/vectors`.
//
// Record format (80 bytes, little endian):
//   0 type u8 | 1 flags u8 | 2 len u8 | 3 rsvd | 4 locate u16 | 6 tracking u16
//   8 timestamp u64 | 16 order_ref u64 | 24 new_ref u64 | 32 shares u64
//   40 price u32 | 44 side u8 | 45 printable u8 | 46 event u8 | 47 rsvd
//   48 match u64 | 56 stock u64 | 64 mpid u32 | 68 ref_value u32
//   72 checksum u32 | 76 rsvd
// =============================================================================
#include <algorithm>
#include <cstdint>
#include <cstring>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <string>
#include <vector>
#include <cstdio>

#include "Vultra_low_latency_nasdaq_itch50_cutthrough.h"
#include "verilated.h"
#include "verilated_cov.h"

static constexpr size_t RECORD_SIZE = 80;
static constexpr size_t DATA_BYTES = 16;

struct Expected {
    uint8_t  type = 0, flags = 0, len = 0, side = 0, printable = 0, event = 0;
    uint16_t locate = 0, tracking = 0;
    uint64_t timestamp = 0, ref = 0, nref = 0, shares = 0, match = 0, stock = 0;
    uint32_t price = 0, mpid = 0, ref_value = 0, checksum = 0;
};

static uint16_t rd16(const uint8_t* p) { return (uint16_t)p[0] | ((uint16_t)p[1] << 8); }
static uint32_t rd32(const uint8_t* p) {
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}
static uint64_t rd64(const uint8_t* p) {
    uint64_t v = 0;
    for (int i = 7; i >= 0; --i) v = (v << 8) | p[i];
    return v;
}

static void wr16(uint8_t* p, uint16_t v) { p[0] = (uint8_t)v; p[1] = (uint8_t)(v >> 8); }
static void wr32(uint8_t* p, uint32_t v) {
    for (int i = 0; i < 4; ++i) p[i] = (uint8_t)(v >> (8 * i));
}
static void wr64(uint8_t* p, uint64_t v) {
    for (int i = 0; i < 8; ++i) p[i] = (uint8_t)(v >> (8 * i));
}

static Expected decode_record(const uint8_t* p) {
    Expected e;
    e.type = p[0]; e.flags = p[1]; e.len = p[2];
    e.locate = rd16(p + 4); e.tracking = rd16(p + 6);
    e.timestamp = rd64(p + 8); e.ref = rd64(p + 16); e.nref = rd64(p + 24);
    e.shares = rd64(p + 32); e.price = rd32(p + 40);
    e.side = p[44]; e.printable = p[45]; e.event = p[46];
    e.match = rd64(p + 48); e.stock = rd64(p + 56);
    e.mpid = rd32(p + 64); e.ref_value = rd32(p + 68); e.checksum = rd32(p + 72);
    return e;
}

static uint32_t fnv1a(const uint8_t* data, size_t n) {
    uint32_t h = 0x811C9DC5u;
    for (size_t i = 0; i < n; ++i) { h ^= data[i]; h *= 0x01000193u; }
    return h;
}

static bool read_file(const std::string& path, std::vector<uint8_t>& out) {
    std::ifstream f(path, std::ios::binary);
    if (!f) return false;
    f.seekg(0, std::ios::end);
    std::streamoff n = f.tellg();
    f.seekg(0, std::ios::beg);
    out.resize((size_t)n);
    f.read(reinterpret_cast<char*>(out.data()), n);
    return true;
}

static uint8_t payload_byte(const Vultra_low_latency_nasdaq_itch50_cutthrough* dut, int i) {
    return (uint8_t)((dut->m_payload[i >> 2] >> ((i & 3) * 8)) & 0xFF);
}

int main(int argc, char** argv) {
    Verilated::commandArgs(argc, argv);
    Verilated::traceEverOn(false);

    std::string vec_dir = "vectors";
    std::string dump_path;
    size_t limit = 0;
    for (int i = 1; i < argc; ++i) {
        std::string a = argv[i];
        if (a == "--vectors" && i + 1 < argc) vec_dir = argv[++i];
        else if (a == "--limit" && i + 1 < argc) limit = std::stoull(argv[++i]);
        else if (a == "--dump" && i + 1 < argc) dump_path = argv[++i];
    }

    std::vector<uint8_t> stream, expected_blob;
    std::vector<uint8_t> dump;
    if (!read_file(vec_dir + "/stream.bin", stream)) {
        std::cerr << "[FAIL] cannot read " << vec_dir << "/stream.bin\n"
                  << "       run: python tb/itch_model.py --count 100000 --out " << vec_dir << "\n";
        return 2;
    }
    if (!read_file(vec_dir + "/expected.bin", expected_blob)) {
        std::cerr << "[FAIL] cannot read " << vec_dir << "/expected.bin\n";
        return 2;
    }
    size_t expected_total = expected_blob.size() / RECORD_SIZE;
    if (limit == 0 || limit > expected_total) limit = expected_total;

    std::cout << "=================================================================\n";
    std::cout << " ITCH 5.0 FULL-FIELD REGRESSION (Verilator vs Python model)\n";
    std::cout << "=================================================================\n";
    std::cout << "[INFO] stream bytes    : " << stream.size() << "\n";
    std::cout << "[INFO] expected records: " << expected_total << " (limit " << limit << ")\n";

    auto* dut = new Vultra_low_latency_nasdaq_itch50_cutthrough;

    // Reset
    dut->clk = 0; dut->rst_n = 0; dut->s_axis_tvalid = 0; dut->s_axis_tlast = 0;
    dut->s_axis_tkeep = 0;
    for (int w = 0; w < 4; ++w) dut->s_axis_tdata[w] = 0;
    for (int i = 0; i < 10; ++i) {
        dut->clk = 0; dut->eval();
        dut->clk = 1; dut->eval();
    }
    dut->rst_n = 1;
    dut->clk = 0; dut->eval();
    dut->clk = 1; dut->eval();

    size_t offset = 0;
    size_t received = 0;
    uint64_t cycles = 0;
    uint64_t first_output_cycle = 0;
    bool first_output_seen = false;
    const uint8_t* expected = expected_blob.data();

    auto fail = [&](const char* what, uint64_t got, uint64_t exp) {
        std::cerr << "[FAIL] pkt " << received << " " << what
                  << " got=" << got << " exp=" << exp << "\n";
        return 1;
    };

    while (received < limit && cycles < (uint64_t)limit * 20u) {
        dut->clk = 0;

        bool feed = (offset < stream.size()) && dut->s_axis_tready;
        if (feed) {
            uint8_t chunk[DATA_BYTES] = {0};
            size_t n = std::min(DATA_BYTES, stream.size() - offset);
            std::memcpy(chunk, stream.data() + offset, n);
            for (int w = 0; w < 4; ++w) {
                dut->s_axis_tdata[w] = (uint32_t)chunk[w * 4] |
                                       ((uint32_t)chunk[w * 4 + 1] << 8) |
                                       ((uint32_t)chunk[w * 4 + 2] << 16) |
                                       ((uint32_t)chunk[w * 4 + 3] << 24);
            }
            // AXI4-Stream: tkeep marks the valid bytes of this beat.
            dut->s_axis_tkeep = (n == DATA_BYTES) ? 0xFFFFu : (uint16_t)((1u << n) - 1u);
            dut->s_axis_tvalid = 1;
            offset += n;
        } else {
            dut->s_axis_tvalid = 0;
            dut->s_axis_tkeep = 0;
        }

        dut->eval();
        dut->clk = 1;
        dut->eval();
        ++cycles;

        if (dut->m_axis_order_valid) {
            if (!first_output_seen) { first_output_seen = true; first_output_cycle = cycles; }
            Expected e = decode_record(expected + received * RECORD_SIZE);

            uint8_t got_flags = (dut->m_is_trade ? 1 : 0) |
                                (dut->m_is_reference ? 2 : 0) |
                                (dut->m_error_corrupt ? 4 : 0);

            if (dut->m_order_type != e.type) return fail("type", dut->m_order_type, e.type);
            if (got_flags != e.flags) return fail("flags", got_flags, e.flags);
            if (dut->m_msg_len != e.len) return fail("len", dut->m_msg_len, e.len);
            if (dut->m_stock_locate != e.locate) return fail("locate", dut->m_stock_locate, e.locate);
            if (dut->m_tracking_number != e.tracking) return fail("tracking", dut->m_tracking_number, e.tracking);
            if (dut->m_timestamp != e.timestamp) return fail("timestamp", dut->m_timestamp, e.timestamp);
            if (dut->m_order_ref_num != e.ref) return fail("order_ref", dut->m_order_ref_num, e.ref);
            if (dut->m_new_order_ref_num != e.nref) return fail("new_ref", dut->m_new_order_ref_num, e.nref);
            if (dut->m_shares != e.shares) return fail("shares", dut->m_shares, e.shares);
            if (dut->m_price != e.price) return fail("price", dut->m_price, e.price);
            if (dut->m_side != e.side) return fail("side", dut->m_side, e.side);
            if (dut->m_printable != e.printable) return fail("printable", dut->m_printable, e.printable);
            if (dut->m_event_code != e.event) return fail("event", dut->m_event_code, e.event);
            if (dut->m_match_number != e.match) return fail("match", dut->m_match_number, e.match);
            if (dut->m_stock != e.stock) return fail("stock", dut->m_stock, e.stock);
            if (dut->m_mpid != e.mpid) return fail("mpid", dut->m_mpid, e.mpid);
            if (dut->m_ref_value != e.ref_value) return fail("ref_value", dut->m_ref_value, e.ref_value);

            uint32_t got_sum = 0;
            if (!dut->m_error_corrupt && dut->m_msg_len > 0) {
                uint8_t buf[64];
                for (int i = 0; i < dut->m_msg_len && i < 64; ++i) buf[i] = payload_byte(dut, i);
                got_sum = fnv1a(buf, dut->m_msg_len);
            }
            if (got_sum != e.checksum) return fail("payload_checksum", got_sum, e.checksum);

            if (!dump_path.empty()) {
                uint8_t rec[RECORD_SIZE] = {0};
                rec[0] = dut->m_order_type;
                rec[1] = got_flags;
                rec[2] = dut->m_msg_len;
                wr16(rec + 4, dut->m_stock_locate);
                wr16(rec + 6, dut->m_tracking_number);
                wr64(rec + 8, dut->m_timestamp);
                wr64(rec + 16, dut->m_order_ref_num);
                wr64(rec + 24, dut->m_new_order_ref_num);
                wr64(rec + 32, dut->m_shares);
                wr32(rec + 40, dut->m_price);
                rec[44] = dut->m_side;
                rec[45] = dut->m_printable;
                rec[46] = dut->m_event_code;
                wr64(rec + 48, dut->m_match_number);
                wr64(rec + 56, dut->m_stock);
                wr32(rec + 64, dut->m_mpid);
                wr32(rec + 68, dut->m_ref_value);
                wr32(rec + 72, got_sum);
                dump.insert(dump.end(), rec, rec + RECORD_SIZE);
            }

            ++received;
            if (received % 100000 == 0)
                std::cout << "[PROGRESS] " << received << " / " << limit << "\n";
        }
    }

    if (received < limit) {
        std::cerr << "[FAIL] only " << received << " / " << limit
                  << " records after " << cycles << " cycles (stalled or dropped)\n";
        return 1;
    }

    // Drain: no extra outputs are allowed.
    for (int i = 0; i < 16; ++i) {
        dut->clk = 0; dut->s_axis_tvalid = 0; dut->eval();
        dut->clk = 1; dut->eval();
        ++cycles;
        if (dut->m_axis_order_valid) {
            std::cerr << "[FAIL] unexpected extra output after " << received << " records\n";
            return 1;
        }
    }

    double sim_ns = cycles * 3.10;
    double gbps = (stream.size() * 8.0) / (cycles * 3.10e-9) / 1e9;
    std::cout << "\n=================================================================\n";
    std::cout << " RESULT\n";
    std::cout << "=================================================================\n";
    std::cout << " Records verified        : " << received << " / " << limit << "\n";
    std::cout << " Full-field mismatches   : 0\n";
    std::cout << " Bytes consumed (model)  : " << stream.size() << "\n";
    std::cout << " status_msg_count        : " << dut->status_msg_count << "\n";
    std::cout << " status_byte_count       : " << dut->status_byte_count << "\n";
    std::cout << " status_corrupt_count    : " << dut->status_corrupt_count << "\n";
    std::cout << " Simulated cycles        : " << cycles << " (" << sim_ns << " ns)\n";
    std::cout << " First output at cycle   : " << first_output_cycle << "\n";
    std::cout << " Throughput (model)      : " << std::fixed << std::setprecision(3) << gbps << " Gbps\n";
    std::cout << "=================================================================\n";

    if (dut->status_msg_count != received) {
        std::cerr << "[FAIL] status_msg_count mismatch\n";
        return 1;
    }
    if (dut->status_byte_count != stream.size()) {
        std::cerr << "[FAIL] byte conservation mismatch: " << dut->status_byte_count
                  << " vs " << stream.size() << "\n";
        return 1;
    }

    VerilatedCov::write("sim_coverage.dat");

    if (!dump_path.empty()) {
        FILE* f = std::fopen(dump_path.c_str(), "wb");
        if (!f) {
            std::cerr << "[FAIL] cannot open dump path " << dump_path << "\n";
            return 1;
        }
        if (!dump.empty()) std::fwrite(dump.data(), 1, dump.size(), f);
        std::fclose(f);
        std::cout << " RTL record dump         : " << dump_path
                  << " (" << dump.size() / RECORD_SIZE << " records)\n";
    }

    delete dut;
    return 0;
}
